-- --- 5. Post-verify gate ----------------------------------------------------
DO $$
DECLARE v_n int; v_gov uuid; v_d text; v_desc int;
BEGIN
  SELECT count(*) INTO v_n FROM essentials.districts
   WHERE mtfcc = 'X0043' AND district_type = 'COUNTY' AND lower(state) = 'ga';
  IF v_n <> 5 THEN RAISE EXCEPTION 'baldwin county structure: expected 5 X0043 districts, got %', v_n; END IF;

  SELECT count(*) INTO v_n FROM essentials.districts
   WHERE geo_id = '13009' AND mtfcc = 'G4020' AND district_type = 'COUNTY';
  IF v_n <> 1 THEN RAISE EXCEPTION 'baldwin county structure: expected exactly 1 Baldwin County Countywide district, got %', v_n; END IF;

  SELECT id INTO v_gov FROM essentials.governments
   WHERE geo_id = '13009' AND type = 'County';
  IF v_gov IS NULL THEN RAISE EXCEPTION 'baldwin county structure: the government row is missing'; END IF;

  SELECT count(*) INTO v_n FROM essentials.chambers WHERE government_id = v_gov;
  IF v_n <> 2 THEN RAISE EXCEPTION 'baldwin county structure: expected 2 chambers, got %', v_n; END IF;

  SELECT count(*) INTO v_n FROM essentials.chambers
   WHERE government_id = v_gov AND ((name = 'Board of Commissioners' AND official_count = 5)
                                 OR (name = 'Elected Officials' AND official_count = 6));
  IF v_n <> 2 THEN RAISE EXCEPTION 'baldwin county structure: chamber names or official_counts are wrong'; END IF;

  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
   WHERE c.government_id = v_gov;
  IF v_n <> 11 THEN RAISE EXCEPTION 'baldwin county structure: expected 11 offices, got %', v_n; END IF;

  -- Exactly one office per numbered district, counted PER DISTRICT. A single
  -- total can hide two offices on one district and none on another.
  FOR v_d IN SELECT 'baldwin-ga-commission-district-' || gs FROM generate_series(1,5) gs LOOP
    SELECT count(*) INTO v_n FROM essentials.offices o
      JOIN essentials.districts d ON d.id = o.district_id
     WHERE d.geo_id = v_d AND d.mtfcc = 'X0043' AND d.district_type = 'COUNTY';
    IF v_n <> 1 THEN RAISE EXCEPTION 'baldwin county structure: district % carries % offices, expected exactly 1', v_d, v_n; END IF;
  END LOOP;

  -- The at-large offices sit on the wide district.
  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
    JOIN essentials.chambers c ON c.id = o.chamber_id
   WHERE c.government_id = v_gov AND d.geo_id = '13009' AND d.mtfcc = 'G4020'
     AND d.district_type = 'COUNTY';
  IF v_n <> 6 THEN RAISE EXCEPTION 'baldwin county structure: expected 6 office(s) on Baldwin County Countywide, got %', v_n; END IF;

  -- 🔴 Ruling R2 must have SURVIVED generation. The Chair and Vice Chair are
  -- roles the Board elects from among its members, recorded as a note on the
  -- SEAT and not as offices of their own. A generator that dropped the
  -- description would pass every count above.
  SELECT count(*) INTO v_desc FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
   WHERE c.government_id = v_gov AND o.description IS NOT NULL AND o.description <> '';
  IF v_desc <> 2 THEN RAISE EXCEPTION 'baldwin county structure: expected 2 office(s) carrying a role note, got %', v_desc; END IF;

  -- And no role leaked out as its own office.
  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
   WHERE c.government_id = v_gov
     AND (o.title ILIKE '%chair%' OR o.title ILIKE '%vice%' OR o.title ILIKE '%pro-tem%' OR o.title ILIKE '%pro tem%');
  IF v_n <> 0 THEN RAISE EXCEPTION 'baldwin county structure: % role(s) were created as offices -- ruling R2 says they are parentheticals', v_n; END IF;

  -- 🔴 No office may sit on a district with no matching boundary: that is an
  -- office nobody can reach by address, and nothing else errors.
  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE c.government_id = v_gov
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries gb
                      WHERE gb.geo_id = d.geo_id AND gb.mtfcc = d.mtfcc);
  IF v_n <> 0 THEN RAISE EXCEPTION 'baldwin county structure: % office(s) sit on a district with no matching boundary', v_n; END IF;

  RAISE NOTICE 'baldwin county structure OK: 5 district(s) created, 1 government, 2 chambers, 11 offices';
END $$;

-- --- 6. People and occupancy, in the SAME migration (spec §3) ---------------

-- --- Politician identity band ----------------------------------------------
-- 🔴 NOBODY ELSE MAY ALREADY OWN THE IDS THIS WAVE IS ABOUT TO INSERT. That is
-- the FL-2 failure exactly: a band collided with 166 existing rows and
-- ON CONFLICT DO NOTHING would have absorbed it in silence, leaving seats held
-- by whoever already owned those ids.
--
-- ⚠ SCOPED TO THIS WAVE'S OWN SUB-RANGE, per the FL-4 correction. A guard over
-- the whole shared band makes a neighbouring wave's legitimate rows look foreign
-- and breaks this migration's OWN re-run. Excluding our own ids keeps it
-- idempotent.
DO $$
DECLARE v_n int; v_foreign text;
BEGIN
  SELECT count(*), string_agg(external_id::text, ', ' ORDER BY external_id)
    INTO v_n, v_foreign
    FROM essentials.politicians
   WHERE external_id BETWEEN -1331018 AND -1331008
     AND external_id NOT IN (-1331018, -1331017, -1331016, -1331015, -1331014, -1331013, -1331012, -1331011, -1331010, -1331009, -1331008);
  IF v_n <> 0 THEN
    RAISE EXCEPTION 'baldwin county people: % row(s) inside this wave''s id range -1331018..-1331008 are owned by something else (%). Pick another sub-range rather than colliding.', v_n, v_foreign;
  END IF;
END $$;

-- 🔴 IDENTITY IS KEYED ON external_id, NEVER ON NAME. All 11 names in this half
-- were checked against production 2026-09-01 with a POSITIVE CONTROL (Floyd
-- Griffin, seated by GA-2, returns exactly 1) and none matched, so all are fresh
-- inserts and nothing is reused. A name-based guard is what seated a Wisconsin
-- village trustee on the Nashville council and a Colorado senator in Georgia.

CREATE TEMP TABLE bc_seed (
  geo_id          text,
  mtfcc           text,
  district_type   text,
  office_title    text,
  ext_id          bigint,
  full_name       text,
  first_name      text,
  last_name       text,
  middle_initial  text,
  name_suffix     text,
  aliases         text[],
  term_start      date,
  start_precision text,
  how_started     text,
  source          text
) ON COMMIT DROP;

